import { readFileSync } from 'node:fs';
import { total } from './total.js';

const pricing = JSON.parse(readFileSync(new URL('./pricing.json', import.meta.url), 'utf8'));
const want = (c) => Math.round(c * (1 + pricing.vat_percent / 100));
let bad = 0;
for (const c of [0, 99, 250, 10000]) {
  const got = total(c);
  if (got !== want(c)) { console.error('total(' + c + ') is ' + got + ', expected ' + want(c)); bad = 1; }
}
process.exit(bad);
